data.script:
src(50) = $price.close
var change = src - src[1]
var up = ema(Math.max(change, 0), options.length)
var down = ema(-Math.min(change, 0), options.length)
var rsiValue = down == 0 ? 100 : up == 0 ? 0 : 100 - (100 / (1 + up / down))
typical(50) = ($price.high + $price.low + $price.close) / 3
var typicalChange = typical - typical[1]
var volume = vbuy + vsell
var positiveFlow = sum(volume * (typicalChange <= 0 ? 0 : typical), options.length)
var negativeFlow = sum(volume * (typicalChange >= 0 ? 0 : typical), options.length)
var mfiValue = !negativeFlow ? null : 100 - (100 / (1 + positiveFlow / negativeFlow))
line(0, color=transparent)
line(100, color=transparent)
line(rsiValue, color=options.rsiColor, lineStyle=0)
line(mfiValue, color=options.mfiColor, lineStyle=2)
